import{_ as a,o as r,c as s,ak as t}from"./chunks/framework.B8jO0odJ.js";const m=JSON.parse('{"title":"Chainy shared task board","description":"The interactive board provides Kanban, Gantt, named task history and reversible Archive. Trello is retired. GitHub issues receive one-way copies; the board remains the editing","frontmatter":{"title":"Chainy shared task board","description":"The interactive board provides Kanban, Gantt, named task history and reversible Archive. Trello is retired. GitHub issues receive one-way copies; the board remains the editing","source":"tools/kanban-sync/README.md","category":"Guides & tooling","sourceUpdated":"2026-10-13T01:56:24+08:00","outline":[2,3]},"headers":[],"relativePath":"content/tools/kanban-sync/readme.md","filePath":"content/tools/kanban-sync/readme.md"}'),o={name:"content/tools/kanban-sync/readme.md"};function i(n,e,d,c,h,l){return r(),s("div",null,[...e[0]||(e[0]=[t('<div><h1 id="chainy-shared-task-board">Chainy shared task board<a class="header-anchor" href="#chainy-shared-task-board" aria-label="Link to this section">​</a></h1><p>The <a href="https://owenlim225.github.io/Chainy-Docs/board/">interactive board</a> provides Kanban, Gantt, named task history and reversible Archive. Trello is retired. GitHub issues receive one-way copies; the board remains the editing surface.</p><h2 id="how-it-works">How it works<a class="header-anchor" href="#how-it-works" aria-label="Link to this section">​</a></h2><p>The static interface lives in <code>tools/team-board/public</code>. One Cloudflare SQLite Durable Object stores the five individual accounts, hashed sessions, cards, audit history and retry queue. A card has one role lane and its matching owner. All five members can read, create, edit, move and archive cards. HTTPS evidence/reference URLs are validated by the service. Version checks prevent stale edits, and operation keys make retries safe.</p><p>Passwords use salted scrypt. The temporary shared first-use password is <code>123</code>; every account must change it to a private password before entering the board. A reset revokes prior sessions. Only password hashes are stored. Sessions expire after 12 hours. Login attempts are limited by account and IP. HTTPS, exact-origin CORS, parameterized SQL, bounded requests and literal-text rendering protect the main service boundaries.</p><h2 id="local-checks-and-operations">Local checks and operations<a class="header-anchor" href="#local-checks-and-operations" aria-label="Link to this section">​</a></h2><p>Run <code>npm run check</code> and <code>npm test</code> from this folder. The board tests use the local Workers runtime and mocked GitHub calls. Run <code>npm run deploy:check</code> before deployment; <code>npx wrangler deploy</code> deploys the service. Run <code>node tools/team-board/check-browser.mjs</code> from the repository root after the service test build for browser checks.</p><p>The administrator token and GitHub token remain deployment secrets. <code>tools/team-board/Manage-Board.ps1</code> reads the existing encrypted administrator token from the Windows user&#39;s local application-data directory. Available actions: <code>Status</code>, <code>Bootstrap</code>, <code>Backup</code>, <code>ResetPassword</code> (requires <code>Username</code>) and <code>SetDefaultPassword</code>. Provisioning does not generate private sign-in handoff files.</p><p>The administrator-only <code>/admin/split-tasks</code> migration archives the 26 original aggregate cards and inserts the 56 role-owned replacement cards once, in a transaction. It checks that every parent is covered and owner lanes, card IDs, dependencies and issue mapping are valid. <code>tools/team-board/Import-Subtasks.ps1</code> reads the committed plan, checks for the five accounts, all 26 old cards and an empty sync queue, then sends the import. A separate export can restore task/history data after a reviewed recovery; there is no public task-import endpoint.</p><p>Keep a dated export before maintenance. The admin and member exports contain tasks and audit history, not credentials. GitHub copies are one-way; the durable queue retries errors with capped backoff. Each additional subtask receives a distinct issue, and the first card in each group reuses its existing issue. New issues recover a lost create response by searching for the unique internal marker. Comments are not mirrored. Only use shareable evidence links because issue copies are public. Never store learner identities, participant records, credentials, signing keys or signed/private URLs in cards, task exports or issues. Do not edit managed issue bodies directly.</p><h2 id="boundaries">Boundaries<a class="header-anchor" href="#boundaries" aria-label="Link to this section">​</a></h2><p>The interface checks for team updates every 10 seconds, not after each keystroke. Game play and SQLite saves remain offline; the management board is separate. The fixed school milestones are November 3–6 and November 21, 2026. The service currently caps the board at 1,000 cards.</p></div>',1)])])}const u=a(o,[["render",i]]);export{m as __pageData,u as default};
